//! Golden values generated by encoding/json from copies of engine-go/types.go.
use engine::types::*;

#[test]
fn types_match_go_json() {
    let golden: Vec<serde_json::Value> = include_str!("go_json_golden.jsonl")
        .lines()
        .map(|line| serde_json::from_str(line).unwrap())
        .collect();
    let stats = StatsResponse {
        download_speed: 0,
        upload_speed: 0,
        progress: 0.0,
        ratio: 0.0,
        torrents: 0,
        ctl_port: 0,
        stream_port: 0,
        path: String::new(),
        payload_transfers_allowed: false,
        listen_port: 0,
    };
    let values = [
        (0, serde_json::to_value(stats).unwrap()),
        (
            1,
            serde_json::to_value(AddRequest {
                torrent_id: String::new(),
                prepare: false,
                torrent_data: Some(String::new()),
            })
            .unwrap(),
        ),
        (
            2,
            serde_json::to_value(AddResponse {
                id: String::new(),
                info_hash: None,
            })
            .unwrap(),
        ),
        (
            3,
            serde_json::to_value(PlayRequest {
                file_index: Some(0),
                ..Default::default()
            })
            .unwrap(),
        ),
        (6, serde_json::to_value(SettingsRequest::default()).unwrap()),
        (7, serde_json::to_value(ArrivalStats::default()).unwrap()),
        (8, serde_json::to_value(SeekStats::default()).unwrap()),
        (
            9,
            serde_json::to_value(TrackerView {
                url: String::new(),
                tier: 0,
                status: String::new(),
                message: Some(String::new()),
                original: false,
            })
            .unwrap(),
        ),
        (
            10,
            serde_json::to_value(OkResponse {
                ok: false,
                id: Some(String::new()),
            })
            .unwrap(),
        ),
    ];
    for (index, actual) in values {
        assert_eq!(actual, golden[index], "Go golden case {index}");
    }
}

#[test]
fn bypass_distinguishes_nil_and_empty_coverage() {
    let mut value = BypassStatus {
        enabled: false,
        active: false,
        mode: "off".into(),
        coverage: None,
        error: None,
    };
    assert_eq!(
        serde_json::to_value(&value).unwrap()["coverage"],
        serde_json::Value::Null
    );
    assert_eq!(
        serde_json::to_value(&value).unwrap()["error"],
        serde_json::Value::Null
    );
    value.coverage = Some(vec![]);
    assert_eq!(
        serde_json::to_value(&value).unwrap()["coverage"],
        serde_json::json!([])
    );
}

#[test]
fn configure_nil_slices_match_go_json() {
    let golden: serde_json::Value = serde_json::from_str(include_str!("go_json_golden.jsonl").lines().nth(4).unwrap()).unwrap();
    let request: ConfigureRequest = serde_json::from_value(golden.clone()).expect("Go nil descriptors/selected must deserialize");
    assert_eq!(serde_json::to_value(request).unwrap(), golden);
}

#[test]
fn select_nil_slices_match_go_json() {
    let golden: serde_json::Value = serde_json::from_str(include_str!("go_json_golden.jsonl").lines().nth(5).unwrap()).unwrap();
    let request: SelectRequest = serde_json::from_value(golden.clone()).expect("Go nil selected must deserialize");
    assert_eq!(serde_json::to_value(request).unwrap(), golden);
}
